// This file is generated by AI.

import { afterEach, describe, expect, it } from 'vitest';

import { actions, appStore } from '../src/state/store.svelte';

describe('updateSettings 的预览开关行为', () => {
  afterEach(() => {
    actions.updateSettings({ autoSyncPreview: true });
  });

  it('关闭实时同步不替换设置对象，其他设置变更和重新开启仍按原行为更新', () => {
    actions.updateSettings({ autoSyncPreview: true });
    actions.beginLivePreview({
      docPath: 'C:\\game\\scene\\test.txt',
      line: 1,
      phase: 'done',
      sceneName: 'test',
    });

    const settingsBeforeClose = appStore.settings;
    actions.updateSettings({ autoSyncPreview: false });

    expect(appStore.settings).toBe(settingsBeforeClose);
    expect(appStore.livePreviewMarker).toBeNull();

    const settingsWhileClosed = appStore.settings;
    actions.updateSettings({ previewMuted: !appStore.settings.previewMuted });
    expect(appStore.settings).not.toBe(settingsWhileClosed);

    const settingsBeforeReopen = appStore.settings;
    actions.updateSettings({ autoSyncPreview: true });
    expect(appStore.settings).not.toBe(settingsBeforeReopen);
  });
});
